const getNewsData = (nodeName) => {
  try {
    const results = $(nodeName).all();
    const data = results[0].json;
    return data.news || data.organic || [];
  } catch (e) {
    return [];
  }
};

const brand1Results = getNewsData('Wardah');
const brand2Results = getNewsData('Camille Beauty');
const brand3Results = getNewsData('Glad2Glow');

const currentTime = DateTime.now().toFormat('yyyy-MM-dd HH:mm');

return [
  ...brand1Results.map(i => ({ json: { ...i, brand: 'Wardah', processedAt: currentTime } })),
  ...brand2Results.map(i => ({ json: { ...i, brand: 'Camille Beauty', processedAt: currentTime } })),
  ...brand3Results.map(i => ({ json: { ...i, brand: 'Glad2Glow', processedAt: currentTime } }))
];

const allItems = $input.all();
const total = allItems.length;

const countBrand = (name) => allItems.filter(i => i.json.brand === name).length;

const counts = {
  nfa: countBrand('Wardah'),
  bisa: countBrand('Camille Beauty'),
  vinix: countBrand('Glad2Glow')
};

const pct = (n) => total > 0 ? ((n / total) * 100).toFixed(1) : '0.0';

const sov = {
  nfa: pct(counts.nfa),
  bisa: pct(counts.bisa),
  vinix: pct(counts.vinix)
};

const combinedText = allItems
  .map(i => `[${i.json.brand}] ${i.json.title || ''} - ${i.json.snippet || ''}`)
  .join('\n');

return [{
  json: {
    metrics: {
      total_mentions: total,
      breakdown: counts,
      share_of_voice: sov
    },
    combinedText
  }

}];

const METRICS_NODE = 'Menyiapkan Teks AI';
const AI_NODE = 'Basic LLM Chain';

const brands = [
  { key: 'nfa',   name: 'Wardah' },
  { key: 'bisa',  name: 'Camille Beauty' },
  { key: 'vinix', name: 'Glad2Glow' }
];

const metrics = $(METRICS_NODE).first().json.metrics;
const rawText = $(AI_NODE).first().json.text || '';

let ai;
try {
  let cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  cleaned = cleaned.substring(start, end + 1);

  // Hapus karakter kontrol yang membuat JSON.parse gagal
  cleaned = cleaned.replace(/[\u0000-\u001F]+/g, ' ');

  ai = JSON.parse(cleaned);
} catch (e) {
  const m = rawText.match(/"executive_summary"\s*:\s*"([\s\S]*?)"\s*,\s*"scores"/);
  ai = {
    executive_summary: m ? m[1] : 'Ringkasan tidak dapat dibaca. Jalankan ulang workflow.',
    scores: [],
    recommendations: []
  };
}

const esc = (s) => String(s ?? '-')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const findScore = (name, idx) => {
  const list = ai.scores || [];
  return list.find(s => String(s.brand).toLowerCase() === name.toLowerCase()) || list[idx] || {};
};

const currentTime = DateTime.now().toFormat('dd LLLL yyyy, HH:mm');

let tableRows = '';
let barRows = '';

brands.forEach((b, i) => {
  const mention = metrics.breakdown[b.key] ?? 0;
  const sov = Number(metrics.share_of_voice[b.key] ?? 0);
  const sc = findScore(b.name, i);

  tableRows += `
    <tr>
      <td><strong>${esc(b.name)}</strong></td>
      <td class="center">${esc(mention)}</td>
      <td class="center">${sov.toFixed(1)}%</td>
      <td class="center score">${esc(sc.score)}/10</td>
      <td class="center">${esc(sc.sentiment)}</td>
      <td>${esc(sc.reason)}</td>
    </tr>`;

  barRows += `
    <div class="bar-row">
      <div class="bar-label">${esc(b.name)}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${sov}%"></div></div>
      <div class="bar-value">${sov.toFixed(1)}%</div>
    </div>`;
});

const recommendations = (ai.recommendations || [])
  .map(r => `<li>${esc(r)}</li>`).join('');

const html = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<style>
  @page { size: A4; margin: 15mm; }
  body { font-family: Arial, Helvetica, sans-serif; color: #222; font-size: 12px; line-height: 1.5; -webkit-print-color-adjust: exact; }
  .header { background: #1f3a93; color: #fff; padding: 20px; border-radius: 6px; }
  .header h1 { margin: 0 0 4px; font-size: 22px; }
  .header p { margin: 0; font-size: 11px; opacity: .9; }
  h2 { color: #1f3a93; border-bottom: 2px solid #e67e22; padding-bottom: 4px; margin-top: 24px; font-size: 15px; }
  .summary { background: #f4f6fb; border-left: 4px solid #1f3a93; padding: 12px 14px; }
  .kpi { display: flex; gap: 10px; margin-top: 12px; }
  .kpi div { flex: 1; background: #fff; border: 1px solid #dde2ee; border-radius: 6px; padding: 10px; text-align: center; }
  .kpi .num { font-size: 20px; font-weight: bold; color: #e67e22; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; }
  th { background: #1f3a93; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
  td { padding: 8px; border-bottom: 1px solid #dde2ee; vertical-align: top; }
  tr:nth-child(even) td { background: #f9fafc; }
  .center { text-align: center; }
  .score { font-weight: bold; color: #1f3a93; }
  .bar-row { display: flex; align-items: center; margin: 8px 0; }
  .bar-label { width: 120px; font-weight: bold; }
  .bar-track { flex: 1; background: #e9ecf3; height: 16px; border-radius: 8px; overflow: hidden; }
  .bar-fill { background: #e67e22; height: 16px; }
  .bar-value { width: 55px; text-align: right; font-weight: bold; }
  .footer { margin-top: 30px; font-size: 10px; color: #888; text-align: center; }
</style>
</head>
<body>
  <div class="header">
    <h1>Laporan Competitor Monitoring</h1>
    <p>Dibuat otomatis pada ${esc(currentTime)}</p>
  </div>

  <h2>Ringkasan Eksekutif</h2>
  <div class="summary">${esc(ai.executive_summary)}</div>
  <div class="kpi">
    <div><div class="num">${esc(metrics.total_mentions)}</div>Total Mention</div>
    <div><div class="num">${brands.length}</div>Brand Dipantau</div>
  </div>

  <h2>Tabel Perbandingan Brand</h2>
  <table>
    <tr>
      <th>Brand</th><th>Mention</th><th>SoV</th>
      <th>Skor Reputasi</th><th>Sentimen</th><th>Alasan</th>
    </tr>
    ${tableRows}
  </table>

  <h2>Share of Voice</h2>
  ${barRows}

  <h2>Rekomendasi Strategis</h2>
  <ul>${recommendations || '<li>Tidak ada rekomendasi.</li>'}</ul>

  <div class="footer">Laporan ini dihasilkan otomatis oleh workflow n8n.</div>
</body>
</html>`;

return [{ json: { html } }];
